mapper.select:
SELECT * FROM cv_experience

    AND status = 1
    AND status = #{query.status}
    AND (INSTR(title, #{query.keyword}) > 0)
    AND experience_type = #{query.experienceType}

ORDER BY sort_order ASC, start_date DESC, experience_id DESC

mapper.update:
UPDATE cv_experience SET experience_type=#{row.experienceType}, title=#{row.title}, subtitle=#{row.subtitle},
logo_url=#{row.logoUrl}, content=#{row.content}, start_date=#{row.startDate}, end_date=#{row.endDate},
sort_order=#{row.sortOrder}, status=#{row.status} WHERE experience_id = #{row.experienceId}
